"""returns a hex string of an int"""
def int_to_hex_string(value: int, length: int = 64) -> str {
    hex_string = str(hex(value))[2:];
    return ("".join(("0" * (length - len(hex_string)))) + hex_string);
}

"""Check if doc has content"""
def doc_has_content(doc: Any) -> object {
    len_title = len(doc['title'].split());
    len_content = len(doc['content'].split());
    return ((len_content - len_title) > 50);
}

"""
    Given total mass of system M, semimajor axis a, and percentage of total mass contained in primary star p,
    calculate positions of binary components keep COM at origin
    (ex: If 1Msol system and MPri = Msec = 0.5 -> M =1 -> p = 0.5)
    Assume stars start a perihelion

    Deprecated

    Parameters
    ----------
    M : float
        Total mass of system (Msol)
    a : float
        Semimajor axis (au)
    e : float
        eccentricity
    p : float
        % of total mass contained in primary (m1)

    Returns
    -------
    x1, x2: float
        Semimajor axes of binary stars assuming that they start at perihelion.
    """
def calcPositions(M: Any = 1, a: Any = 1, e: Any = 0, p: Any = 0.5) -> object {
    m1 = p * M;
    m2 = M - m1;
    a1 = (m2 / M) * a;
    a2 = (m1 / M) * a;
    x1 = (a1 * (1 - (e * e))) / (1 + e);
    x2 = (-1 * a2 * (1 - (e * e))) / (1 + e);
    return (x1, x2);
}

"""Add support for aliasing to make some names shorter & allow minor mistakes"""
def alias(name: str) -> str {
    aliases = {
        "cpp": "c++",
        "jb": "jetbrains",
        "javascript": "node",
        "js": "node",
        "py": "python"
    };
    return aliases.get(name, name);
}

