"""
    Indent the lines in a string by padding each one with proper number of pad
    characters
    """
def indent(lines: Any, amount: Any, ch: Any = " ") -> object {
    padding = amount * ch;
    return (padding + ("\n" + padding).join(lines.split("\n")));
}
